cd /home/diogenes/Projects/twyne; cat >> src/global.css <<'EOF'

/* ── Flow: the margins the conductor fills ─────────────────────────
   Room on the right (notes, replies, sources, works, the charter),
   the writer's own archive on the left. Cards are index slips pinned
   level with their passage; hover draws a proofreader's bracket and a
   pencil line from slip to text. */
.flow-surface {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.flow-surface > * {
  pointer-events: auto;
}
.flow-overlay {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none !important;
}
.flow-overlay__line,
.flow-overlay__bracket {
  fill: none;
  stroke-width: 1.25;
  stroke-linecap: round;
  opacity: 0.8;
}
.flow-overlay__line {
  stroke-dasharray: 600;
  stroke-dashoffset: 600;
  animation: flow-draw 420ms ease-out forwards;
}
.flow-overlay__line.is-dashed {
  stroke-dasharray: 3 4;
  stroke-dashoffset: 0;
  animation: none;
  opacity: 0.55;
}
.flow-overlay__mark {
  opacity: 0.45;
}
@keyframes flow-draw {
  to {
    stroke-dashoffset: 0;
  }
}
.flow-column {
  position: absolute;
  top: 0;
  bottom: 0;
}
.flow-column--room {
  left: calc(100% + 28px);
}
.flow-column--archive {
  right: calc(100% + 28px);
}
.flow-card {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  padding: 0.65rem 0.75rem 0.6rem;
  background: var(--color-paper);
  border: 1px solid var(--color-paper-3);
  border-top: 3px solid var(--flow-accent, var(--color-sage));
  border-radius: 1px;
  color: var(--color-ink);
  font: 0.84rem/1.5 var(--font-serif);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 10px 22px -18px rgb(0 0 0 / 0.45);
  transition:
    top 220ms cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 160ms ease,
    box-shadow 160ms ease;
  animation: flow-slip-in 280ms ease-out;
}
.flow-column--archive .flow-card {
  border-top-width: 1px;
  border-left: 3px solid var(--flow-accent, var(--color-cobalt));
  background: color-mix(in srgb, var(--color-paper) 88%, var(--color-cobalt) 4%);
}
.flow-card.is-hovered {
  transform: translateY(-1px);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 14px 28px -16px rgb(0 0 0 / 0.5);
  z-index: 3;
}
@keyframes flow-slip-in {
  from {
    opacity: 0;
    transform: translateX(10px);
  }
}
.flow-column--archive .flow-card {
  animation-name: flow-slip-in-left;
}
@keyframes flow-slip-in-left {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
}
.flow-card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}
.flow-card__kicker {
  font: 0.62rem/1.2 var(--font-typewriter);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--flow-accent, var(--color-ink-muted));
}
.flow-card__close {
  border: 0;
  background: none;
  color: var(--color-ink-muted);
  font-size: 0.7rem;
  cursor: pointer;
  opacity: 0;
  transition: opacity 120ms ease;
}
.flow-card:hover .flow-card__close,
.flow-card:focus-within .flow-card__close {
  opacity: 1;
}
.flow-card__close:hover {
  color: var(--color-vermilion);
}
.flow-card__body {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.flow-card__title {
  font-family: var(--font-display);
  font-size: 0.86rem;
  font-weight: 700;
  line-height: 1.3;
}
.flow-card__text {
  color: var(--color-ink-light);
}
/* An echo reads as a carbon copy of the writer's own page. */
.flow-card__carbon {
  font-family: var(--font-typewriter);
  font-size: 0.72rem;
  line-height: 1.55;
  color: color-mix(in srgb, var(--color-cobalt) 70%, var(--color-ink));
  opacity: 0.9;
}
.flow-card__reply {
  margin: 0;
  padding: 0.45rem 0 0 0.6rem;
  border-left: 1px solid var(--flow-accent, var(--color-paper-3));
  color: var(--color-ink);
  font-style: italic;
}
.flow-card__reply-by {
  display: block;
  font: normal 0.6rem/1.3 var(--font-typewriter);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.flow-card__reply.is-streaming::after {
  content: "▍";
  margin-left: 1px;
  color: var(--flow-accent, var(--color-ink));
  animation: flow-caret 1s steps(2) infinite;
}
@keyframes flow-caret {
  50% {
    opacity: 0;
  }
}
.flow-card__foot {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font: 0.62rem/1.3 var(--font-typewriter);
  color: var(--color-ink-muted);
}
.flow-card__notice {
  margin: 0;
  font-size: 0.72rem;
  color: var(--color-ink-muted);
}
.flow-link {
  border: 0;
  padding: 0;
  background: none;
  color: var(--color-cobalt);
  font: 0.7rem var(--font-typewriter);
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}
.flow-link:disabled {
  opacity: 0.5;
  cursor: default;
}
.flow-mini {
  padding: 0.15rem 0.6rem;
  font-size: 0.72rem;
}
/* A rubber stamp, slightly askew, for the charter and amendments. */
.flow-stamp {
  position: absolute;
  top: 0.55rem;
  right: 1.6rem;
  padding: 0.05rem 0.35rem;
  border: 1.5px solid var(--color-vermilion);
  border-radius: 2px;
  color: var(--color-vermilion);
  font: 0.58rem/1.3 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transform: rotate(-4deg);
  opacity: 0.75;
  mix-blend-mode: multiply;
}
.flow-amend {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.flow-amend__input {
  width: 100%;
  padding: 0.4rem 0.5rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
  color: var(--color-ink);
  font: 0.8rem/1.45 var(--font-typewriter);
  resize: vertical;
}
.flow-amend__input:focus {
  outline: 1px solid var(--color-vermilion);
}
.flow-amend__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
/* Works: a book stands upright; a record sits in its sleeve with the
   disc peeking out. */
.flow-work {
  display: flex;
  gap: 0.7rem;
  color: inherit;
  text-decoration: none;
}
.flow-work__sleeve {
  position: relative;
  flex-shrink: 0;
}
.flow-work__sleeve img,
.flow-work__blank {
  position: relative;
  z-index: 1;
  display: block;
  width: 72px;
  object-fit: cover;
  background: var(--color-paper-2);
  box-shadow:
    1px 1px 0 var(--color-paper-3),
    3px 5px 10px -6px rgb(0 0 0 / 0.5);
}
.flow-work--book .flow-work__sleeve img,
.flow-work--book .flow-work__blank {
  height: 108px;
  border-radius: 1px 3px 3px 1px;
}
.flow-work--album .flow-work__sleeve img,
.flow-work--song .flow-work__sleeve img,
.flow-work--album .flow-work__blank,
.flow-work--song .flow-work__blank {
  height: 72px;
}
.flow-work__blank {
  display: grid;
  place-items: center;
  font: 700 1.6rem var(--font-display);
  color: var(--color-ink-muted);
}
.flow-work__disc {
  position: absolute;
  top: 4px;
  left: 18px;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background:
    radial-gradient(circle, var(--color-mustard) 0 14%, #111 15% 17%, transparent 18%),
    repeating-radial-gradient(circle, #1a1a1a 0 1px, #262626 1px 3px);
  transition: transform 240ms ease;
}
.flow-work:hover .flow-work__disc {
  transform: translateX(14px) rotate(40deg);
}
.flow-work__text {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}
.flow-work__medium {
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.flow-work__text strong {
  font-family: var(--font-display);
  line-height: 1.25;
}
.flow-work__text span:last-child {
  font-size: 0.76rem;
  color: var(--color-ink-light);
}
.flow-waiting {
  position: absolute;
  left: 0;
  padding: 0.2rem 0.55rem;
  border: 1px dashed var(--color-paper-3);
  border-radius: 999px;
  background: var(--color-paper);
  color: var(--color-ink-muted);
  font: 0.64rem var(--font-typewriter);
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: top 220ms ease;
}
.flow-waiting:hover {
  color: var(--color-ink);
  border-style: solid;
}
.flow-dock {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: var(--z-dropdown);
  width: min(300px, calc(100vw - 32px));
  pointer-events: auto;
}
.flow-dock .flow-card {
  position: relative;
}
.flow-dock__more {
  margin: 0.3rem 0 0;
  font: 0.62rem var(--font-typewriter);
  color: var(--color-ink-muted);
  text-align: right;
}

/* The chrome eases out as a run builds and stays out in flow. The page
   itself never moves. */
[data-flow="settling"] .editor-workspace-main > header,
[data-flow="settling"] .twyne-toolbar,
[data-flow="settling"] .in-flow-rails,
[data-flow="settling"] .flow-surface {
  opacity: 0.4;
  transition: opacity 1.2s ease;
}
[data-flow="flow"] .flow-surface,
[data-flow="flow"] .in-flow-rails {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.8s ease;
}
[data-flow="settling"] .editor-workspace-main > header:hover,
[data-flow="settling"] .twyne-toolbar:hover {
  opacity: 1;
}
[data-flow="stuck"] .flow-card {
  animation: flow-slip-in 360ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  .flow-card,
  .flow-overlay__line,
  .flow-work__disc,
  [data-flow] .editor-workspace-main > header {
    animation: none;
    transition: none;
  }
  .flow-overlay__line {
    stroke-dashoffset: 0;
  }
}
@media print {
  .flow-surface,
  .flow-dock {
    display: none !important;
  }
}
EOF
